# Datetime format support (R5)
def dt_format_to_regex(dt_format):
    """Convert a strftime-style datetime format string to a regex pattern.

    Supports standard C locale strftime directives:
      %Y - 4-digit year
      %m - month (01-12), single digit allowed (1-12)
      %d - day of month (01-31), single digit allowed (1-31)
      %H - hour (00-23)
      %M - minute (00-59)
      %S - second (00-60)
      %f - fractional seconds (variable length, 1-6 digits)
      %z - UTC offset (+HHMM, -HHMM, +HH:MM, -HH:MM, or empty)
      %j - day of year (001-366)
      %u - weekday (1-7, Monday=1)
      %w - weekday (0-6, Sunday=0)
      %A - full weekday name (case-insensitive)
      %a - abbreviated weekday name (case-insensitive)
      %B - full month name (case-insensitive)
      %b, %h - abbreviated month name (case-insensitive)
      %p - AM/PM indicator (case-insensitive)
      %% - literal percent sign

    Returns a compiled regex pattern object.
    """
    return get_regex_for_datetime_format(dt_format)


def _datetime_format_to_regex_inner(dt_format):
    """Internal function to convert datetime format to regex string."""
    i = 0
    result = []
    while i < len(dt_format):
        if dt_format[i] == '%':
            if i + 1 >= len(dt_format):
                raise ValueError("Incomplete format directive at end of string")
            directive = dt_format[i+1]
            i += 2

            if directive == '%':
                result.append(r'\%')
            elif directive == 'Y':
                result.append(r'(\d{4})')
            elif directive == 'y':
                result.append(r'(\d{2})')
            elif directive == 'm':
                # Month: 01-12, but also allow 1-12 (single digit)
                result.append(r'(?:0[1-9]|1[0-2]|[1-9])')
            elif directive == 'd':
                # Day: 01-31, but also allow 1-31 (single digit)
                result.append(r'(?:0[1-9]|[12]\d|3[01]|[1-9])')
            elif directive == 'e':
                # Day with space padding (1-31)
                result.append(r'(?:\s?\d|[12]\d|3[01]|[1-9])')
            elif directive == 'H':
                # Hour: 00-23
                result.append(r'(?:[01]\d|2[0-3])')
            elif directive == 'I':
                # Hour 12-hour: 01-12
                result.append(r'(?:0[1-9]|1[0-2])')
            elif directive == 'M':
                # Minute: 00-59
                result.append(r'(?:[0-5]\d)')
            elif directive == 'S':
                # Second: 00-60 (allowing leap second)
                result.append(r'(?:[0-5]\d|60)')
            elif directive == 'f':
                # Fractional seconds: variable length (1-6 digits)
                result.append(r'(\d{1,6})')
            elif directive == 'L':
                # Milliseconds (exactly 3 digits)
                result.append(r'(\d{3})')
            elif directive == 'N':
                # Nanoseconds (exactly 9 digits)
                result.append(r'(\d{9})')
            elif directive == 'z':
                # Timezone offset: +HHMM, -HHMM, +HH:MM, -HH:MM, Z, or empty
                result.append(
                    r'(?:Z|[+-](?:\d{2}(?::?\d{2})?)?|(?<!\d))'
                )
            elif directive == 'Z':
                # Timezone name (generic)
                result.append(r'([A-Za-z]+)')
            elif directive == 'j':
                # Day of year: 001-366
                result.append(r'(?:0[0-9]\d|1\d{2}|2\d{2}|3[0-5]\d|36[0-6])')
            elif directive == 'u':
                # Weekday: 1-7 (Monday=1)
                result.append(r'(?:[1-7])')
            elif directive == 'w':
                # Weekday: 0-6 (Sunday=0)
                result.append(r'(?:[0-6])')
            elif directive == 'U':
                # Week number (Sunday first): 00-53
                result.append(r'(?:0\d|1\d|2\d|3[0-2]|5[0-3])')
            elif directive == 'W':
                # Week number (Monday first): 00-53
                result.append(r'(?:0\d|1\d|2\d|3[0-2]|5[0-3])')
            elif directive == 'A':
                # Full weekday name
                result.append(
                    r'(?:Monday|Tuesday|Wednesday|Thursday|Friday|'
                    r'Saturday|Sunday)'
                )
            elif directive == 'a':
                # Abbreviated weekday name
                result.append(
                    r'(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun)'
                )
            elif directive == 'B':
                # Full month name
                result.append(
                    r'(?:January|February|March|April|May|June|'
                    r'July|August|September|October|November|December)'
                )
            elif directive in ('b', 'h'):
                # Abbreviated month name
                result.append(
                    r'(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)'
                )
            elif directive == 'p':
                # AM/PM
                result.append(r'(?:AM|PM|am|pm|Am|Pm|aM|pM)')
            else:
                # Unknown directive, treat as literal
                result.append(re.escape('%' + directive))
        else:
            # Literal character
            if dt_format[i] in '.*+?^$(){}[]|\\':
                result.append('\\' + dt_format[i])
            else:
                result.append(dt_format[i])
            i += 1

    return ''.join(result)


def get_regex_for_datetime_format(dt_format):
    """Get a compiled regex for a datetime format string.

    This is a convenience wrapper around dt_format_to_regex that returns
    a compiled re.Pattern object instead of the raw string.

    Args:
        dt_format: A strftime-style datetime format string.

    Returns:
        A compiled regular expression pattern.
    """
    pattern = _datetime_format_to_regex_inner(dt_format)
    return re.compile(pattern)


def strf_date_convert(match, fmt):
    """Convert a regex match group dict back to a datetime using strftime.

    This function takes a dictionary of named groups from a datetime regex
    match and a format string, and reconstructs the datetime string by
    replacing each % directive with the corresponding matched value.

    Args:
        match: A dictionary mapping group names to their matched values.
               For positional groups, use keys like 'group_0', 'group_1', etc.
        fmt: The original strftime format string used to generate the regex.

    Returns:
        A string with all % directives replaced by their matched values.
    """
    result = []
    i = 0
    group_idx = [0]  # Use list for mutability in closure

    def get_group_value(directive):
        # Try to get value from match dict
        key = f'group_{group_idx[0]}'
        group_idx[0] += 1
        if key in match:
            val = match[key]
            # Handle leading zeros for certain directives
            if directive in ('m', 'd', 'H', 'I', 'M', 'S'):
                if len(val) == 1:
                    return f'0{val}'
            return val
        return ''

    while i < len(fmt):
        if fmt[i] == '%':
            if i + 1 >= len(fmt):
                raise ValueError("Incomplete format directive at end of string")
            directive = fmt[i+1]
            i += 2

            if directive == '%':
                result.append('%')
            elif directive == 'z':
                # For timezone offsets, we need special handling
                key = f'group_{group_idx[0]}'
                group_idx[0] += 1
                if key in match and match[key]:
                    result.append(match[key])
                else:
                    result.append('')
            else:
                result.append(get_group_value(directive))
        else:
            result.append(fmt[i])
            i += 1

    return ''.join(result)


class TooManyFields(Exception):
    """Raised when too many fields are found in a format string."""

    def __init__(self, expected, actual):
        self.expected = expected
        self.actual = actual
        super().__init__(
            f'{actual} field(s) specified, {expected} expected'
        )


